Action.Str:
/* Read-only preflight: no volume, route, DND or lock settings are changed. */
import android.app.KeyguardManager;
import android.app.NotificationManager;
import android.media.AudioManager;
import android.media.AudioDeviceInfo;
import android.os.PowerManager;
import android.os.Build;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
pm = context.getSystemService("power");
km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked())
    throw new JavaCodeException("Turn on and unlock the phone before controlling Signia");
am = context.getSystemService("audio");
nm = context.getSystemService("notification");
streamName = tasker.getVariable("SIG3_AudioStream");
if (!"media".equals(streamName) && !"ring".equals(streamName))
    throw new JavaCodeException("Set SIG3_AudioStream to Signia's selected media or ring stream");
stream = "ring".equals(streamName) ? AudioManager.STREAM_RING : AudioManager.STREAM_MUSIC;
volume = am.getStreamVolume(stream);
maximum = am.getStreamMaxVolume(stream);
mode = am.getMode();
ringer = am.getRingerMode();
minimumText = tasker.getVariable("SIG3_MinAudioPercent");
minimumPercent = 50;
if (minimumText != null && !minimumText.equals("") && !minimumText.startsWith("%")) {
    if (!minimumText.matches("[0-9]{1,3}"))
        throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
    minimumPercent = Integer.parseInt(minimumText);
}
if (minimumPercent < 1 || minimumPercent > 100)
    throw new JavaCodeException("Set SIG3_MinAudioPercent to an integer from 1 to 100");
required = (maximum * minimumPercent + 99) / 100;
filter = nm.getCurrentInterruptionFilter();
outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS);
route = "";
external = false;
for (device : outputs) {
    type = device.getType();
    route = route + type + ":" + device.getProductName() + ";";
    /* Known connected external outputs; presence is conservative, not an active-route claim. */
    if (type == 3 || type == 4 || type == 7 || type == 8 || type == 11 || type == 12 || type == 22 || type == 23 || type == 26 || type == 27)
        external = true;
}
tasker.setVariable("SIG3_AudioDiagnostics", "stream=" + streamName + " volume=" + volume + "/" + maximum + "; minimum=" + required + "/" + maximum + "; ringerMode=" + ringer + "; mode=" + mode + "; interruptionFilter=" + filter + "; outputs=" + route);
/* BEGIN AUDIO POLICY: also exercised without Android by the policy test. */
if (filter != NotificationManager.INTERRUPTION_FILTER_ALL)
    throw new JavaCodeException("Turn off Do Not Disturb (including bedtime/night mode), then retry the Signia command");
if (ringer == AudioManager.RINGER_MODE_SILENT || ("ring".equals(streamName) && ringer != AudioManager.RINGER_MODE_NORMAL))
    throw new JavaCodeException("Unmute the phone; for Ring sound, also turn off vibrate-only mode, then retry");
if (maximum <= 0 || volume < required)
    throw new JavaCodeException("Raise phone " + streamName + " volume with the phone volume slider to at least " + required + "/" + maximum + " (" + minimumPercent + "% minimum), then retry");
/* END AUDIO POLICY */
if (mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION)
    throw new JavaCodeException("Phone call or communication audio is active");
if (external) throw new JavaCodeException("Disconnect external audio outputs before acoustic control");
return "ready";

} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* BEGIN PICKER DETECTION */
pickerProgram(root) {
    if(root==null||root.getPackageName()==null||!"com.signia.rta".contentEquals(root.getPackageName()))return "";
    queue=new java.util.ArrayList();queue.add(root);heading=0;selected=0;program="";
    for(scan=0;scan<queue.size()&&scan<300;scan++) {
        node=queue.get(scan);
        if(node.isVisibleToUser()&&node.isEnabled()) {
            text=node.getText();description=node.getContentDescription();
            if(text!=null&&"Programs".equals(text.toString()))heading++;
            if(description!=null&&description.toString().endsWith(" Selected Button")) {
                name=description.toString().substring(0,description.toString().length()-" Selected Button".length());
                matches=0;for(slot=1;slot<=6;slot++)if(name.equals(tasker.getVariable("SIG3_ProgramName"+slot)))matches++;
                if(matches!=1)throw new JavaCodeException("Program picker selection is not uniquely configured");
                selected++;program=name;
            }
        }
        for(childIndex=0;childIndex<node.getChildCount();childIndex++) {
            child=node.getChild(childIndex);if(child!=null)queue.add(child);
        }
    }
    if(queue.size()>300)throw new JavaCodeException("Program picker tree exceeds inspection limit");
    if(heading==0)return "";
    if(heading!=1||selected!=1)throw new JavaCodeException("Cannot identify selected program in picker");
    return program;
}
/* END PICKER DETECTION */
controlsLabel(root) {
    if(root==null||root.getPackageName()==null||!"com.signia.rta".contentEquals(root.getPackageName()))return "";
    queue=new java.util.ArrayList();queue.add(root);labels=0;headers=0;label="";header="";
    id=tasker.getVariable("SIG3_ProgramId");
    for(scan=0;scan<queue.size()&&scan<300;scan++) {
        node=queue.get(scan);
        if(node.isVisibleToUser()&&node.isEnabled()) {
            text=node.getText();description=node.getContentDescription();
            if(id!=null&&id.equals(node.getViewIdResourceName())&&text!=null&&text.toString().trim().length()>0){labels++;label=text.toString().trim();}
            if(description!=null&&description.toString().startsWith("Hearing program ")&&description.toString().endsWith(" Active")) {
                headers++;header=description.toString().substring(16,description.toString().length()-7).trim();
            }
        }
        for(i=0;i<node.getChildCount();i++){child=node.getChild(i);if(child!=null)queue.add(child);}
    }
    if(queue.size()>300||headers>1||labels>1)return "";
    if(labels==1&&(headers==0||label.equals(header)))return label;
    return labels==0&&headers==1?header:"";
}
prepareProgramRead(service) {
    root=service.getRootInActiveWindow();picker=pickerProgram(root);
    if(root==null||root.getPackageName()==null||!"com.signia.rta".contentEquals(root.getPackageName()))throw new JavaCodeException("Signia is not foreground");
    queue=new java.util.ArrayList();queue.add(root);battery=0;pageId=tasker.getVariable("SIG3_BatteryPageId");
    for(scan=0;scan<queue.size()&&scan<300;scan++) {
        node=queue.get(scan);
        if(node.isVisibleToUser()&&node.isEnabled()&&pageId!=null&&pageId.equals(node.getViewIdResourceName()))battery++;
        for(i=0;i<node.getChildCount();i++){child=node.getChild(i);if(child!=null)queue.add(child);}
    }
    if(queue.size()>300||battery>1||(battery==1&&picker.length()>0))throw new JavaCodeException("Signia page is ambiguous");
    if(battery==0&&picker.length()==0)return root;
    if(!service.performGlobalAction(1))throw new JavaCodeException("Could not return to Signia Controls");
    for(attempt=0;attempt<20;attempt++) {
        android.os.SystemClock.sleep(150);root=service.getRootInActiveWindow();current=controlsLabel(root);
        if(current.length()>0) {
            if(picker.length()>0&&!picker.equals(current))throw new JavaCodeException("Program changed while returning to Controls; retry");
            return root;
        }
    }
    throw new JavaCodeException("Signia Controls did not return; open Controls and retry");
}

/* Opens battery UI and records visible information; never invents acoustic percentages. */
import android.view.accessibility.AccessibilityNodeInfo;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.os.SystemClock;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
visibleTree(service) {
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    visible = new java.util.ArrayList();
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        if (node.isVisibleToUser() && node.isEnabled()) visible.add(node);
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex); if (child != null) queue.add(child);
        }
    }
    return visible;
}
matching(nodes, id, description) {
    found = new java.util.ArrayList();
    for (node : nodes) {
        if (id != null && id.equals(node.getViewIdResourceName())) found.add(node);
    }
    if (found.size() == 0 && description != null && description.length() > 0 && !description.startsWith("%")) {
        for (node : nodes) if (node.getContentDescription() != null && description.contentEquals(node.getContentDescription())) found.add(node);
    }
    return found;
}
try {
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
info = service.getServiceInfo();
if (info == null) throw new JavaCodeException("Tasker accessibility information unavailable");
info.flags = info.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS; service.setServiceInfo(info);
mode = tasker.getVariable("par1");
if (!"open".equals(mode) && !"listen".equals(mode)) throw new JavaCodeException("Battery mode must be open or listen");
pageId = tasker.getVariable("SIG3_BatteryPageId");
if (pageId == null || pageId.length() == 0 || pageId.startsWith("%")) throw new JavaCodeException("Configure SIG3_BatteryPageId");
if (pickerProgram(service.getRootInActiveWindow()).length() > 0) prepareProgramRead(service);
nodes = visibleTree(service);
page = matching(nodes, pageId, null);
if (page.size() > 1) throw new JavaCodeException("Battery page marker is ambiguous");
if (page.size() == 0) {
    open = matching(nodes, tasker.getVariable("SIG3_BatteryOpenId"), tasker.getVariable("SIG3_BatteryOpenDescription"));
    if (open.size() != 1) throw new JavaCodeException("Battery opener missing/ambiguous; configure its captured ID or description");
    found = (AccessibilityNodeInfo) open.get(0); clicked = false;
    for (depth = 0; found != null && depth < 5; depth++) {
        if (found.isClickable()) {
            if (!found.performAction(AccessibilityNodeInfo.ACTION_CLICK)) throw new JavaCodeException("Battery click rejected");
            clicked = true; break;
        }
        found = found.getParent();
    }
    if (!clicked) throw new JavaCodeException("Battery opener has no clickable ancestor");
    for (attempt = 0; attempt < 20; attempt++) {
        SystemClock.sleep(150);
        nodes = visibleTree(service); page = matching(nodes, pageId, null);
        if (page.size() > 1) throw new JavaCodeException("Battery page marker is ambiguous");
        if (page.size() == 1) break;
    }
    if (page.size() != 1) throw new JavaCodeException("Battery page marker missing; configure SIG3_BatteryPageId");
}
text = "";
for (node : nodes) if (node.getText() != null) text = text + node.getText() + "\n";
tasker.setVariable("SIG3_BatteryText", text);
tasker.setVariable("SIG3_Observed", "Battery page opened; visible text recorded. No aid battery percentage inferred.");
return "opened";
} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString()); throw failure;
}
